#!/usr/bin/env python3
"""Offline campaign CLI; JSON stdin/stdout, diagnostics on stderr."""
import json
import math
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent / "src"))

LIMIT = 64 * 1024 * 1024


def pairs(items):
    value = {}
    for key, item in items:
        if key in value:
            raise ValueError("duplicate key")
        value[key] = item
    return value


def strict_loads(raw):
    def bad(value):
        raise ValueError("nonfinite")

    def finite(value):
        result = float(value)
        if not math.isfinite(result):
            raise ValueError("nonfinite")
        return result

    return json.loads(raw.decode("utf-8"), object_pairs_hook=pairs,
                      parse_constant=bad, parse_float=finite)


def read_document():
    raw = sys.stdin.buffer.read(LIMIT + 1)
    if len(raw) > LIMIT:
        raise ValueError("input cap")
    return strict_loads(raw)


def main():
    sys.setrecursionlimit(20000)
    document = None
    try:
        document = read_document()
    except (ValueError, UnicodeError, RecursionError, OSError):
        document = None
        result = {"error": "INVALID_INPUT"}
    else:
        try:
            from eywa.offline import execute
            result = execute(document)
        except BaseException as exc:  # pragma: no cover - defensive only
            sys.stderr.write("campaign error: %r\n" % (exc,))
            result = {"error": "INVALID_INPUT"}
    try:
        text = json.dumps(result, ensure_ascii=True, separators=(",", ":"),
                          allow_nan=False)
    except BaseException as exc:  # pragma: no cover - defensive only
        sys.stderr.write("encoding error: %r\n" % (exc,))
        text = '{"error":"INVALID_INPUT"}'
    sys.stdout.write(text)
    sys.stdout.write("\n")
    sys.stdout.flush()


if __name__ == "__main__":
    main()
